function createObserver() {
  const listeners: Array<() => void> = []
  return {
    subscribe(fn: () => void) {
      listeners.push(fn)
      return () => listeners.splice(listeners.indexOf(fn), 1)
    },
    notify() {
      listeners.forEach((fn) => fn())
    },
  }
}

const store = createObserver()
store.subscribe(() => console.log('changed'))
store.notify()

